/** Why ALOOKHOR — [alookhor_why_alookhor]. */
if(!defined('ABSPATH'))exit;
function alookhor_cc_why_defaults(){return ['enabled'=>true,'eyebrow'=>'WHY ALOOKHOR','title'=>'چرا آلوخور را انتخاب می‌کنید؟','subtitle'=>'ما از باغ تا سفره، کیفیت را در هر مرحله تضمین می‌کنیم تا بهترین تجربه از طعم واقعی آلو خشک را برای شما فراهم کنیم.','image_id'=>0,'image_url'=>ALOOKHOR_CC_URL.'assets/images/category-plums.jpg','badge_title'=>'آلوخور','badge_text'=>'کیفیتی که می‌چشید، اعتمادی که می‌ماند','background'=>'#0B0716','card'=>'#12091A','gold'=>'#D4A436','text'=>'#FFFFFF','muted'=>'#C8BDCC','radius'=>20,'items'=>[
 ['icon'=>'natural','title'=>'انتخاب محصول','description'=>'انتخاب دقیق بهترین آلوها از باغ‌های معتبر و سالم'],['icon'=>'quality','title'=>'کنترل کیفیت','description'=>'بررسی و کنترل کیفیت در تمام مراحل پردازش و بسته‌بندی'],['icon'=>'medal','title'=>'تجربه و اعتبار','description'=>'سال‌ها فعالیت در صنعت خشکبار و صادرات به بازارهای جهانی'],['icon'=>'heart','title'=>'رضایت مشتریان','description'=>'اعتماد مشتریان داخلی و خارجی، حاصل کیفیت و تعهد ماست']], 'stats'=>[
 ['icon'=>'calendar','value'=>'+15','label'=>'سال تجربه در صنعت خشکبار'],['icon'=>'box','value'=>'+6','label'=>'محصول متنوع و باکیفیت'],['icon'=>'users','value'=>'+1,000','label'=>'مشتریان عمده و خرده'],['icon'=>'globe','value'=>'+50','label'=>'کشور هدف صادراتی']]];}
function alookhor_cc_get_why_settings(){$state=alookhor_cc_get_settings();$saved=is_array($state['why_settings']??null)?$state['why_settings']:[];$defaults=alookhor_cc_why_defaults();$settings=array_replace_recursive($defaults,$saved);foreach($defaults['items'] as $i=>$item){foreach(['icon','title','description'] as $key)if(trim((string)($settings['items'][$i][$key]??''))==='')$settings['items'][$i][$key]=$item[$key];}foreach($defaults['stats'] as $i=>$stat){foreach(['icon','value','label'] as $key)if(trim((string)($settings['stats'][$i][$key]??''))==='')$settings['stats'][$i][$key]=$stat[$key];}if(empty($settings['image_id'])&&trim((string)($settings['image_url']??''))==='')$settings['image_url']=$defaults['image_url'];if(trim((string)($settings['badge_title']??''))==='')$settings['badge_title']=$defaults['badge_title'];if(trim((string)($settings['badge_text']??''))==='')$settings['badge_text']=$defaults['badge_text'];if(trim((string)($settings['title']??''))==='چرا آلوخور را انتخاب کنید؟')$settings['title']=$defaults['title'];if(trim((string)($settings['subtitle']??''))==='تضمین ارگانیک بودن، نظارت مستمر و کیفیت بی‌رقیب خشکبار خراسان')$settings['subtitle']=$defaults['subtitle'];if(in_array(strtoupper((string)($settings['background']??'')),['#1C1025','#2B0A3D'],true))$settings['background']=$defaults['background'];if(in_array(strtoupper((string)($settings['card']??'')),['#26213D','#1D1126'],true))$settings['card']=$defaults['card'];return $settings;}
function alookhor_cc_why_icon($name){$p=['heart'=>'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21.2l8.8-8.8a5.5 5.5 0 0 0 0-7.8Z"/>','medal'=>'<circle cx="12" cy="9" r="6"/><path d="m8 14-1 8 5-3 5 3-1-8M12 6v6M9 9h6"/>','quality'=>'<path d="M12 2 15 5l4-.2.2 4L22 12l-2.8 3.2-.2 4-4-.2-3 3-3-3-4 .2-.2-4L2 12l2.8-3.2.2-4 4 .2 3-3Z"/><path d="m9 12 2 2 4-5"/>','natural'=>'<path d="M12 21V10M12 16c-6 0-9-4-9-9 6 0 9 4 9 9Zm0-4c0-6 4-9 9-9 0 6-4 9-9 9Z"/>','calendar'=>'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/>','box'=>'<path d="m4 7 8-4 8 4-8 4-8-4Zm0 0v10l8 4 8-4V7M12 11v10"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>','globe'=>'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 4 6 4 9s-1 6-4 9c-3-3-4-6-4-9s1-6 4-9Z"/>'];return '<svg viewBox="0 0 24 24" aria-hidden="true">'.($p[$name]??$p['quality']).'</svg>';}
function alookhor_cc_why_image($s){$id=absint($s['image_id']??0);if($id){$url=wp_get_attachment_image_url($id,'full');if($url)return $url;}return esc_url_raw($s['image_url']??'');}
function alookhor_cc_why_shortcode(){$s=alookhor_cc_get_why_settings();if(empty($s['enabled']))return '';$c=[];foreach(['background','card','gold','text','muted'] as $k)$c[$k]=sanitize_hex_color($s[$k]??'')?:alookhor_cc_why_defaults()[$k];$image=alookhor_cc_why_image($s);ob_start();static $style=false;if(!$style&&alookhor_cc_should_inline_shortcode_css()){$style=true;$f=ALOOKHOR_CC_DIR.'assets/css/frontend-why-alookhor.css';if(file_exists($f))echo '<style id="alookhor-why-inline">'.file_get_contents($f).'</style>';}?>
<section id="why-alookhor" class="alookhor-why" dir="rtl" style="--awy-bg:<?php echo esc_attr($c['background']);?>;--awy-card:<?php echo esc_attr($c['card']);?>;--awy-gold:<?php echo esc_attr($c['gold']);?>;--awy-text:<?php echo esc_attr($c['text']);?>;--awy-muted:<?php echo esc_attr($c['muted']);?>;--awy-radius:<?php echo max(12,min(36,absint($s['radius'])));?>px"><div class="awy-inner"><div class="awy-layout"><aside class="awy-visual"><?php if($image):?><img src="<?php echo esc_url($image);?>" alt="محصولات ممتاز آلوخور" loading="lazy"><?php endif;?><div class="awy-brand-badge"><i><?php echo alookhor_cc_why_icon('natural');?></i><b><?php echo esc_html($s['badge_title']);?></b><p><?php echo esc_html($s['badge_text']);?></p></div></aside><div class="awy-content"><header><span><?php echo alookhor_cc_why_icon('natural');?></span><small><?php echo esc_html($s['eyebrow']);?></small><h2><?php echo esc_html($s['title']);?></h2><i></i><p><?php echo esc_html($s['subtitle']);?></p></header><div class="awy-grid"><?php foreach((array)$s['items'] as $index=>$item):?><article><i><?php echo alookhor_cc_why_icon($item['icon']??'quality');?></i><h3><?php echo esc_html($item['title']??'');?></h3><p><?php echo esc_html($item['description']??'');?></p><span><b><?php echo esc_html(sprintf('%02d',$index+1));?></b></span></article><?php endforeach;?></div></div></div><div class="awy-stats"><?php foreach((array)$s['stats'] as $stat):if(empty($stat['value']))continue;?><span><i><?php echo alookhor_cc_why_icon($stat['icon']??'quality');?></i><b><?php echo esc_html($stat['value']);?></b><small><?php echo esc_html($stat['label']);?></small></span><?php endforeach;?></div></div></section><?php return ob_get_clean();}
add_shortcode('alookhor_why_alookhor','alookhor_cc_why_shortcode');add_shortcode('alookhor_why_us','alookhor_cc_why_shortcode');add_action('wp_enqueue_scripts',function(){wp_enqueue_style('alookhor-cc-why',ALOOKHOR_CC_URL.'assets/css/frontend-why-alookhor.css',[],ALOOKHOR_CC_BUILD);wp_enqueue_script('alookhor-cc-why',ALOOKHOR_CC_URL.'assets/js/frontend-why-alookhor.js',[],ALOOKHOR_CC_BUILD,true);});
